mapper.select:
SELECT id, user_id, scene, submission_token, request_hash, status,
       response_data, create_time, expires_at
FROM tb_http_submission
WHERE user_id = #{userId}
  AND scene = #{scene}
  AND submission_token = #{submissionToken}
LIMIT 1

mapper.insert:
INSERT INTO tb_http_submission (
    user_id, scene, submission_token, request_hash, status,
    response_data, create_time, expires_at
) VALUES (
    #{userId}, #{scene}, #{submissionToken}, #{requestHash}, #{status},
    #{responseData}, #{createTime}, #{expiresAt}
)

mapper.update:
UPDATE tb_http_submission
SET status = 'SUCCEEDED',
    response_data = #{responseData}
WHERE id = #{id}
  AND status = 'PROCESSING'

mapper.delete:
DELETE FROM tb_http_submission
WHERE status = 'SUCCEEDED'
  AND expires_at <= #{before}
ORDER BY id
LIMIT #{limit}
